// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Why a `blocked` write has stopped.
 */

public enum BlockedReason: Equatable, Hashable {
    
    case credentialRefused
    case keySpent
    case ancestorUnavailable
    case conflictUnresolved
    case awaitingDependency





}

#if compiler(>=6)
extension BlockedReason: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockedReason: FfiConverterRustBuffer {
    typealias SwiftType = BlockedReason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockedReason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .credentialRefused
        
        case 2: return .keySpent
        
        case 3: return .ancestorUnavailable
        
        case 4: return .conflictUnresolved
        
        case 5: return .awaitingDependency
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlockedReason, into buf: inout [UInt8]) {
        switch value {
        
        
        case .credentialRefused:
            writeInt(&buf, Int32(1))
        
        
        case .keySpent:
            writeInt(&buf, Int32(2))
        
        
        case .ancestorUnavailable:
            writeInt(&buf, Int32(3))
        
        
        case .conflictUnresolved:
            writeInt(&buf, Int32(4))
        
        
        case .awaitingDependency:
            writeInt(&buf, Int32(5))
        
        }
    }
}


