// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum Hydration: Equatable, Hashable {
    
    case never
    case inProgress
    case complete
    case expired





}

#if compiler(>=6)
extension Hydration: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHydration: FfiConverterRustBuffer {
    typealias SwiftType = Hydration

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Hydration {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .never
        
        case 2: return .inProgress
        
        case 3: return .complete
        
        case 4: return .expired
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Hydration, into buf: inout [UInt8]) {
        switch value {
        
        
        case .never:
            writeInt(&buf, Int32(1))
        
        
        case .inProgress:
            writeInt(&buf, Int32(2))
        
        
