/**
 * Every variant carries `message`, the core's own sentence for it, because
 * UniFFI renders an error's description by reflection otherwise.
 */
public enum MarfaError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotFound(code: String, message: String
    )
    case Unauthorized(code: String, message: String
    )
    case Forbidden(code: String, message: String
    )
    case Validation(code: String, message: String
    )
    case UnknownType(message: String
    )
    case RateLimited(code: String, message: String, retryAfterSeconds: UInt64?
    )
    case Server(status: UInt16, code: String, message: String
    )
    case Network(message: String
    )
    case Decoding(message: String
    )
    case Store(message: String
    )
    case NoServer(message: String
    )
    case NoCursor(message: String
    )
    case HydrationIncomplete(message: String
    )
    case WrongSchema(expected: String, found: String, 
        /**
         * The store the caller has to discard. Carried rather than left in
         * the message, because a Swift caller showing this to a person has
         * to be able to name the file without parsing prose out of it.
         */path: String, message: String
    )
    case ReadingHandle(message: String
    )
    case CatchUpTooOld(minRetainedId: String, message: String
    )
    case StreamIncomplete(reason: String, message: String
    )
    case WrongServer(expected: String, got: String, message: String
    )
    /**
     * The item is whole and its bytes are not here, nor can they be fetched.
     */
    case BytesAbsent(hash: String, reason: String, message: String
    )
    case Invalid(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension MarfaError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMarfaError: FfiConverterRustBuffer {
    typealias SwiftType = MarfaError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MarfaError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Unauthorized(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Forbidden(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Validation(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .UnknownType(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .RateLimited(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf), 
            retryAfterSeconds: try FfiConverterOptionUInt64.read(from: &buf)
            )
        case 7: return .Server(
            status: try FfiConverterUInt16.read(from: &buf), 
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Decoding(
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Store(
            message: try FfiConverterString.read(from: &buf)
            )
        case 11: return .NoServer(
            message: try FfiConverterString.read(from: &buf)
            )
        case 12: return .NoCursor(
            message: try FfiConverterString.read(from: &buf)
            )
        case 13: return .HydrationIncomplete(
            message: try FfiConverterString.read(from: &buf)
            )
        case 14: return .WrongSchema(
            expected: try FfiConverterString.read(from: &buf), 
            found: try FfiConverterString.read(from: &buf), 
            path: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 15: return .ReadingHandle(
            message: try FfiConverterString.read(from: &buf)
            )
        case 16: return .CatchUpTooOld(
            minRetainedId: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 17: return .StreamIncomplete(
            reason: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 18: return .WrongServer(
            expected: try FfiConverterString.read(from: &buf), 
            got: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 19: return .BytesAbsent(
            hash: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 20: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MarfaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(code,message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unauthorized(code,message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Forbidden(code,message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Validation(code,message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .UnknownType(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .RateLimited(code,message,retryAfterSeconds):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            FfiConverterOptionUInt64.write(retryAfterSeconds, into: &buf)
            
        
        case let .Server(status,code,message):
            writeInt(&buf, Int32(7))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Network(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Decoding(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Store(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NoServer(message):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NoCursor(message):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .HydrationIncomplete(message):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .WrongSchema(expected,found,path,message):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(found, into: &buf)
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ReadingHandle(message):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .CatchUpTooOld(minRetainedId,message):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(minRetainedId, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .StreamIncomplete(reason,message):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(reason, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .WrongServer(expected,got,message):
            writeInt(&buf, Int32(18))
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(got, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .BytesAbsent(hash,reason,message):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(hash, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Invalid(message):
            writeInt(&buf, Int32(20))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


