// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What the server made of a write: one of six, and absent while the write
 * is unanswered.
 */

public enum Verdict: Equatable, Hashable {
    
    case accepted
    /**
     * The server applied the write over changes made since, field by field.
     */
    case merged(fields: [String]
    )
    /**
     * The server kept its own value and wrote the losing one to a sibling.
     */
    case conflicted(siblingId: String, fields: [String]
    )
    /**
     * The server's code verbatim, or the sentence naming the write this one
     * waited on where that write was refused.
     */
    case refused(reason: String
    )
    case blocked(reason: BlockedReason
    )
    /**
     * Refused until the ceiling; released by id. The row's `answer` holds
     * the last answer it got.
     */
    case dead





}

#if compiler(>=6)
extension Verdict: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVerdict: FfiConverterRustBuffer {
    typealias SwiftType = Verdict

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Verdict {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .accepted
        
        case 2: return .merged(fields: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 3: return .conflicted(siblingId: try FfiConverterString.read(from: &buf), fields: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 4: return .refused(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .blocked(reason: try FfiConverterTypeBlockedReason.read(from: &buf)
        )
        
        case 6: return .dead
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Verdict, into buf: inout [UInt8]) {
        switch value {
        
        
        case .accepted:
            writeInt(&buf, Int32(1))
        
        
        case let .merged(fields):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceString.write(fields, into: &buf)
            
        
        case let .conflicted(siblingId,fields):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(siblingId, into: &buf)
            FfiConverterSequenceString.write(fields, into: &buf)
            
        
        case let .refused(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .blocked(reason):
            writeInt(&buf, Int32(5))
            FfiConverterTypeBlockedReason.write(reason, into: &buf)
            
        
        case .dead:
            writeInt(&buf, Int32(6))
        
        }
    }
}


